INSERT INTO public.answers (id, public_ref, api_version, site_id, channel, language, question_text, parent_answer_id, topic, outcome, reading_level, official_blocks, ai_explanation, caveats, follow_ups, clarification, gap_description, review_reasons, case_id, guideline_id, validation_result, ai_provider, ai_model, prompt_version, latency_ms, review_flag, review_flag_reason, is_demo_seed, created_at) VALUES ('6f15f0b4-5456-4755-921a-cf8b618b66b0', 'ANS-FYWTk2bG5r8', 'v1', NULL, 'api', 'en', 'What was the unemployment rate in South Africa in the latest quarter?', NULL, 'unemployment', 'answered', 'short', '[{"type": "metric", "unit": "percent", "label": "Official unemployment rate", "source": {"url": "https://www.statssa.gov.za/publications/P0211/P02112ndQuarter2025.pdf", "title": "Quarterly Labour Force Survey, Quarter 2: 2025 (P0211)", "publisher": "Statistics South Africa", "pageNumber": null, "publishedOn": "2025-08-12", "sectionLabel": null, "versionLabel": "P0211 · Q2 2025", "referencePeriod": "Q2 2025 (April–June 2025)", "sourceVersionId": "7f6529fe-625a-4ada-808e-78d62ccf97a1"}, "geography": "South Africa", "adjustment": "Not seasonally adjusted", "population": "Labour force aged 15–64", "valueState": "reported", "displayValue": "33.2%", "reportedChange": "Up 0.3 of a percentage point from 32.9% in Q1 2025", "referencePeriod": "Q2 2025 (April–June 2025)", "comparabilityNote": null}, {"type": "metric", "unit": "percent", "label": "Expanded unemployment rate", "source": {"url": "https://www.statssa.gov.za/publications/P0211/P02112ndQuarter2025.pdf", "title": "Quarterly Labour Force Survey, Quarter 2: 2025 (P0211)", "publisher": "Statistics South Africa", "pageNumber": null, "publishedOn": "2025-08-12", "sectionLabel": null, "versionLabel": "P0211 · Q2 2025", "referencePeriod": "Q2 2025 (April–June 2025)", "sourceVersionId": "7f6529fe-625a-4ada-808e-78d62ccf97a1"}, "geography": "South Africa", "adjustment": "Not seasonally adjusted", "population": "Labour force aged 15–64 including discouraged work-seekers", "valueState": "reported", "displayValue": "42.9%", "reportedChange": "Down 0.2 of a percentage point from Q1 2025", "referencePeriod": "Q2 2025 (April–June 2025)", "comparabilityNote": null}, {"rows": [{"Unit": "percent", "Value": "33.2%", "Period": "Q2 2025 (April–June 2025)", "Source": "Statistics South Africa", "Measure": "Official unemployment rate", "Geography": "South Africa", "Publication": "Quarterly Labour Force Survey, Quarter 2: 2025 (P0211) (P0211 · Q2 2025)"}, {"Unit": "percent", "Value": "42.9%", "Period": "Q2 2025 (April–June 2025)", "Source": "Statistics South Africa", "Measure": "Expanded unemployment rate", "Geography": "South Africa", "Publication": "Quarterly Labour Force Survey, Quarter 2: 2025 (P0211) (P0211 · Q2 2025)"}], "type": "dataset", "title": "Verified figures used in this answer", "columns": ["Measure", "Value", "Unit", "Geography", "Period", "Source", "Publication"], "sources": [{"url": "https://www.statssa.gov.za/publications/P0211/P02112ndQuarter2025.pdf", "title": "Quarterly Labour Force Survey, Quarter 2: 2025 (P0211)", "publisher": "Statistics South Africa", "pageNumber": null, "publishedOn": "2025-08-12", "sectionLabel": null, "versionLabel": "P0211 · Q2 2025", "referencePeriod": "Q2 2025 (April–June 2025)", "sourceVersionId": "7f6529fe-625a-4ada-808e-78d62ccf97a1"}, {"url": "https://www.statssa.gov.za/publications/P0211/P02112ndQuarter2025.pdf", "title": "Quarterly Labour Force Survey, Quarter 2: 2025 (P0211)", "publisher": "Statistics South Africa", "pageNumber": null, "publishedOn": "2025-08-12", "sectionLabel": null, "versionLabel": "P0211 · Q2 2025", "referencePeriod": "Q2 2025 (April–June 2025)", "sourceVersionId": "7f6529fe-625a-4ada-808e-78d62ccf97a1"}], "fileName": "statbridge-verified-figures.csv", "rowCount": 2}, {"text": "The official unemployment rate was 33.2% in the second quarter of 2025, up 0.3 of a percentage point from 32.9% in the first quarter of 2025.", "type": "official_quote", "source": {"url": "https://www.statssa.gov.za/publications/P0211/P02112ndQuarter2025.pdf", "title": "Quarterly Labour Force Survey, Quarter 2: 2025 (P0211)", "publisher": "Statistics South Africa", "pageNumber": null, "publishedOn": "2025-08-12", "sectionLabel": "Key findings", "versionLabel": "P0211 · Q2 2025", "referencePeriod": "Q2 2025 (April–June 2025)", "sourceVersionId": "7f6529fe-625a-4ada-808e-78d62ccf97a1"}}, {"text": "The expanded unemployment rate, which includes discouraged work-seekers, stood at 42.9% in Q2 2025.", "type": "official_quote", "source": {"url": "https://www.statssa.gov.za/publications/P0211/P02112ndQuarter2025.pdf", "title": "Quarterly Labour Force Survey, Quarter 2: 2025 (P0211)", "publisher": "Statistics South Africa", "pageNumber": null, "publishedOn": "2025-08-12", "sectionLabel": "Key findings", "versionLabel": "P0211 · Q2 2025", "referencePeriod": "Q2 2025 (April–June 2025)", "sourceVersionId": "7f6529fe-625a-4ada-808e-78d62ccf97a1"}}]', 'The official unemployment rate for South Africa was 33.2% in the second quarter of 2025. This covers the labour force aged 15–64. In the same period, the expanded unemployment rate was 42.9%, which includes discouraged work-seekers.', '{}', '{"How many people were unemployed in South Africa in Q2 2025?","What was the change in the official unemployment rate between Q1 2025 and Q2 2025?","What was the expanded unemployment rate in Q2 2025?"}', NULL, NULL, '{}', NULL, 'f949a04b-4301-40bf-b601-1d8c4865d253', '{"evidence_count": 4, "proposal_decision": "answer"}', 'Google Gemini (direct API key)', 'gemini-3.8-flash', 'ask-2026-09-1', 8785, 'none', NULL, false, '2026-09-18 08:50:21.504512+00');
INSERT INTO public.answers (id, public_ref, api_version, site_id, channel, language, question_text, parent_answer_id, topic, outcome, reading_level, official_blocks, ai_explanation, caveats, follow_ups, clarification, gap_description, review_reasons, case_id, guideline_id, validation_result, ai_provider, ai_model, prompt_version, latency_ms, review_flag, review_flag_reason, is_demo_seed, created_at) VALUES ('45a0cd86-c964-4447-96a0-d262c00083c7', 'ANS-FXzJNPuPQEU', 'v1', NULL, 'api', 'en', 'How many people live in Gauteng?', NULL, 'gauteng population', 'answered', 'short', '[{"type": "metric", "unit": "people", "label": "Population of Gauteng", "source": {"url": "https://www.statssa.gov.za/publications/P0302/P03022025.pdf", "title": "Mid-year population estimates, 2025 (P0302)", "publisher": "Statistics South Africa", "pageNumber": 1, "publishedOn": "2025-07-28", "sectionLabel": null, "versionLabel": "P0302 · 2025", "referencePeriod": "Mid-2025", "sourceVersionId": "b5145c82-6f45-445c-a754-8bab12ea529a"}, "geography": "Gauteng", "adjustment": null, "population": "All residents", "valueState": "reported", "displayValue": "16.1 million", "reportedChange": null, "referencePeriod": "Mid-2025", "comparabilityNote": null}, {"type": "metric", "unit": "percent", "label": "Gauteng share of national population", "source": {"url": "https://www.statssa.gov.za/publications/P0302/P03022025.pdf", "title": "Mid-year population estimates, 2025 (P0302)", "publisher": "Statistics South Africa", "pageNumber": 1, "publishedOn": "2025-07-28", "sectionLabel": null, "versionLabel": "P0302 · 2025", "referencePeriod": "Mid-2025", "sourceVersionId": "b5145c82-6f45-445c-a754-8bab12ea529a"}, "geography": "Gauteng", "adjustment": null, "population": "All residents", "valueState": "reported", "displayValue": "25.5%", "reportedChange": null, "referencePeriod": "Mid-2025", "comparabilityNote": null}, {"text": "Gauteng remains the most populous province with about 16.1 million people, roughly 25.5% of the national total, at mid-2025.", "type": "official_quote", "source": {"url": "https://www.statssa.gov.za/publications/P0302/P03022025.pdf", "title": "Mid-year population estimates, 2025 (P0302)", "publisher": "Statistics South Africa", "pageNumber": 1, "publishedOn": "2025-07-28", "sectionLabel": "Provincial distribution", "versionLabel": "P0302 · 2025", "referencePeriod": "Mid-2025", "sourceVersionId": "b5145c82-6f45-445c-a754-8bab12ea529a"}}]', 'At mid-2025, Gauteng had an estimated population of 16.1 million people. This covers all residents living in the province. This made up 25.5% of South Africa''s total population.', '{}', '{"What was the total population of South Africa at mid-2025?","What percentage of South Africa''s population lived in Gauteng at mid-2025?"}', NULL, NULL, '{}', NULL, 'f949a04b-4301-40bf-b601-1d8c4865d253', '{"evidence_count": 3, "proposal_decision": "answer"}', 'Google Gemini (direct API key)', 'gemini-3.8-flash', 'ask-2026-09-1', 3843, 'none', NULL, false, '2026-09-18 08:50:32.657912+00');
