INSERT INTO public.passages (id, source_version_id, "position", page_number, section_label, content, created_at) VALUES ('549ecdcc-c3f5-4c6c-a1d1-0c4599573232', 'b5145c82-6f45-445c-a754-8bab12ea529a', 1, 1, 'Key findings', 'South Africa''s population is estimated at 63.1 million people at mid-2025, according to the Mid-year population estimates release (P0302).', '2026-09-18 06:02:13.880645+00');
INSERT INTO public.passages (id, source_version_id, "position", page_number, section_label, content, created_at) VALUES ('6330904d-9650-49eb-9797-64957c261c63', 'b5145c82-6f45-445c-a754-8bab12ea529a', 2, 1, 'Provincial distribution', 'Gauteng remains the most populous province with about 16.1 million people, roughly 25.5% of the national total, at mid-2025.', '2026-09-18 06:02:13.880645+00');
INSERT INTO public.passages (id, source_version_id, "position", page_number, section_label, content, created_at) VALUES ('e6cfd763-355d-420e-b508-ddf4a6d43264', '683c5465-3de9-421c-8743-074fba10b5ff', 1, NULL, 'Key finding', 'Census 2022 counted a population of 62 million people in South Africa on census night, 2 February 2022.', '2026-09-18 06:02:13.880645+00');
INSERT INTO public.passages (id, source_version_id, "position", page_number, section_label, content, created_at) VALUES ('9cee2966-1e2c-4bd9-84c9-201a1fb3d909', '7f6529fe-625a-4ada-808e-78d62ccf97a1', 1, NULL, 'Key findings', 'The official unemployment rate was 33.2% in the second quarter of 2025, up 0.3 of a percentage point from 32.9% in the first quarter of 2025.', '2026-09-18 06:02:13.880645+00');
INSERT INTO public.passages (id, source_version_id, "position", page_number, section_label, content, created_at) VALUES ('8e03f7de-86d2-4f30-8c37-a343a5643d9f', '7f6529fe-625a-4ada-808e-78d62ccf97a1', 2, NULL, 'Key findings', 'The number of unemployed persons rose to 8.4 million in Q2 2025, from 8.2 million in Q1 2025.', '2026-09-18 06:02:13.880645+00');
INSERT INTO public.passages (id, source_version_id, "position", page_number, section_label, content, created_at) VALUES ('4f94700b-f6fa-439b-abf5-e9ecd7273f0d', '7f6529fe-625a-4ada-808e-78d62ccf97a1', 3, NULL, 'Key findings', 'The expanded unemployment rate, which includes discouraged work-seekers, stood at 42.9% in Q2 2025.', '2026-09-18 06:02:13.880645+00');
INSERT INTO public.passages (id, source_version_id, "position", page_number, section_label, content, created_at) VALUES ('89e89e08-09f9-4bd6-a06f-1f50b892e5f3', '096e9a56-dfea-409e-bec5-a5136ba922b4', 1, NULL, 'Key finding', 'Annual headline consumer price inflation was 3.4% in September 2025.', '2026-09-18 06:02:13.880645+00');
INSERT INTO public.passages (id, source_version_id, "position", page_number, section_label, content, created_at) VALUES ('67ffdeca-eee5-4a80-bab8-1372f85476c9', '9f78875f-f31f-41ef-aa71-2331234451d4', 1, NULL, 'Key finding', 'Real gross domestic product grew by 0.8% in the second quarter of 2025 (quarter on quarter, seasonally adjusted), following growth of 0.1% in the first quarter.', '2026-09-18 06:02:13.880645+00');
INSERT INTO public.passages (id, source_version_id, "position", page_number, section_label, content, created_at) VALUES ('a5797d45-1230-4749-800c-741a10944e1d', 'dff8267e-6e72-4732-a862-d6fb6583b8bf', 1, NULL, 'Decision', 'The Monetary Policy Committee of the South African Reserve Bank decided unanimously to reduce the repurchase rate to 6.75%, effective 20 November 2025.', '2026-09-18 06:02:13.880645+00');
INSERT INTO public.passages (id, source_version_id, "position", page_number, section_label, content, created_at) VALUES ('6f33d08f-986c-42fe-a30b-1bf1d37c4c21', '86a1bc48-8c1b-41ad-9259-a962075b4a35', 1, NULL, 'Key findings', 'In 2023, 42.3% of households in South Africa were headed by females. The share was highest in Eastern Cape (48.8%) and lowest in Gauteng (36.5%).', '2026-09-18 06:02:13.880645+00');
INSERT INTO public.passages (id, source_version_id, "position", page_number, section_label, content, created_at) VALUES ('8a5747f6-ded1-45fa-a120-435e07d65db1', '86a1bc48-8c1b-41ad-9259-a962075b4a35', 2, NULL, 'Key findings', 'Receipt of social grants rose to 39.4% of households/individuals in 2023, up from 30.9% in 2019.', '2026-09-18 06:02:13.880645+00');
INSERT INTO public.passages (id, source_version_id, "position", page_number, section_label, content, created_at) VALUES ('8e2b07a5-f876-4454-9af1-8cbbf9faaac4', '111f0f90-6b12-4b0e-bd2c-5d4c8520c680', 1, NULL, 'Consolidated fiscal framework', 'The May 2025 Budget projects a consolidated budget deficit of 4.8% of GDP for 2025/26, narrowing to 3.4% of GDP by 2027/28.', '2026-09-18 06:02:13.880645+00');
